bool XFTextStyle::Equal(IXFStyle* pStyle)
{
    if (!pStyle || pStyle->GetStyleFamily() != enumXFStyleText)
    {
        return false;
    }

    XFTextStyle* pOther = dynamic_cast<XFTextStyle*>(pStyle);
    if (!pOther)
    {
        return false;
    }

    if (m_pFont.is())
    {
        if (!pOther->m_pFont.is())
            return false;
        if (*m_pFont != *pOther->m_pFont)
            return false;
    }
    else if (pOther->m_pFont.is())
        return false;

    return true;
}
enumXFStyle XFTextStyle::GetStyleFamily() { return enumXFStyleText; }
void XFTextStyle::ToXml(IXFStream* strm)
{
    IXFAttrList* pAttrList = strm->GetAttrList();
    OUString style = GetStyleName();

    pAttrList->Clear();
    if (!style.isEmpty())
        pAttrList->AddAttribute(u"style:name"_ustr, GetStyleName());
    if (!GetParentStyleName().isEmpty())
        pAttrList->AddAttribute(u"style:parent-style-name"_ustr, GetParentStyleName());

    pAttrList->AddAttribute(u"style:family"_ustr, u"text"_ustr);
    strm->StartElement(u"style:style"_ustr);

    //Font properties:
    pAttrList->Clear();
    //font name:
    if (m_pFont.is())
        m_pFont->ToXml(strm);

    strm->StartElement(u"style:properties"_ustr);
    strm->EndElement(u"style:properties"_ustr);

    strm->EndElement(u"style:style"_ustr);
}
